// Validate Evaluation Output
const raw = $json.text;
if (!raw || typeof raw !== 'string') {
  throw new Error('Evaluator returned no output.');
}

const cleaned = raw
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let evalResult;
try {
  evalResult = JSON.parse(cleaned);
} catch (e) {
  throw new Error(`Invalid evaluator JSON: ${e.message}`);
}

const score = Number(evalResult.score);
if (!Number.isFinite(score) || score < 0 || score > 100) {
  throw new Error(`Score must be between 0 and 100, received ${score}`);
}

return {
  json: {
    challengeId: evalResult.challengeId || 'act_prob_771',
    score: Math.round(score),
    feedback: evalResult.feedback || 'Evaluation complete.',
    evidence: evalResult.evidence || 'Passed test suite.',
    skill: evalResult.skill || 'Statistics'
  }
};
